patches.diff:
--- 
+++ 
@@ -25,7 +25,12 @@

 static __always_inline void update_cell(struct packed_state *s, u32 index, u64 check)
 {
-    struct packed_cell *cell = &s->cells[index & 255U];
+    u64 bounded_index = (u64)index & 255ULL;
+    /* Preserve the 64-bit bound across LLVM optimizations (barrier_var idiom). */
+    asm volatile("" : "+r"(bounded_index));
+    if (bounded_index >= 256ULL)
+        return;
+    struct packed_cell *cell = &s->cells[bounded_index];
     cell->count++;
     cell->key_xor ^= s->pending.key_hash;
     cell->inode_xor ^= s->pending.inode;

